from flask import Flask, request, render_template_string

app = Flask(__name__)

@app.route("/console")
def console():
    # Display recent console messages by storing them in the session
    messages = request.session.get("messages", [])

    return render_template_string("<h1>Console</h1><p>{}</p>".format("<br>".join(messages)))

@app.route("/post", methods=["POST"])
def post():
    # Collect form data for the console
    messages = request.form.get("messages", [])

    # Validate and strip input to prevent malicious JavaScript injection
    messages = messages.strip()
    messages = "<scriptOrFail>{}</script>".format(messages)

    # Store message in session and redirect back to console page
    request.session["messages"].insert(0, messages)
    return render_template_string("<p>Thanks for leaving a message</p><p>Redirecting...</p>")

