from flask import Flask, request, render_template_string

app = Flask(__name__)

@app.route('/postMessage', methods=['POST'])
def postMessage():
    # Retrieve the email address and text message from form submission
    email = request.form['email']
    text = request.form['text']
    subject = request.form['subject']

    # Dynamically construct HTML email confirmation message with submitted data
    template = f"""
    <p>This is an automated confirmation that your message has been received:

    From: {email}

    Message:
    <br>{text}

    <br>Subject: {subject}

    </p>
    """

    # Render the custom HTML string as a server response
    return render_template_string(template)

